SELECT PetType, AVG(pet_age) AS avg_age, MAX(pet_age) AS max_age
FROM Pets
GROUP BY PetType;

SELECT PetType, AVG(pet_age) AS avg_age, MAX(pet_age) AS max_age
FROM Pets
GROUP BY PetType;

SELECT StuID, COUNT(PetID) AS pet_count
FROM Has_Pet
GROUP BY StuID;

SELECT DISTINCT c.CountryId, c.CountryName
FROM countries c
JOIN car_makers cm ON cm.Country = c.CountryId;

SELECT Model, COUNT(*) AS version_count
FROM car_names
