SELECT SourceAirport, COUNT(*) AS flight_count
FROM flights
GROUP BY SourceAirport;

SELECT DestAirport, COUNT(*) AS flight_count
FROM flights
GROUP BY DestAirport;

SELECT d.Document_ID, d.Document_Name, t.Template_ID, t.Template_Type_Code
FROM Documents d
JOIN Templates t ON d.Template_ID = t.Template_ID;

SELECT Template_Type_Code, COUNT(*) AS Template_Count
FROM Templates
GROUP BY Template_Type_Code;

SELECT Document_ID, COUNT(*) AS paragraph_count
