SELECT h.ID, h.name, h.grade
FROM Highschooler h
WHERE h.ID NOT IN (SELECT student_id FROM Friend);

SELECT DISTINCT d.age
FROM Dogs d
JOIN Treatments t ON d.dog_id = t.dog_id;

SELECT first_name FROM Owners
UNION
SELECT last_name FROM Owners;

SELECT owner_id, COUNT(*) AS dog_count
FROM Dogs
GROUP BY owner_id;

SELECT treatment_type_code, SUM(cost_of_treatment) AS total_cost
FROM Treatments
